+------------------------------+
| Eingabe: laenge, breite      |
+------------------------------+
| flaeche ← laenge * breite    |
+------------------------------+
| Ausgabe: flaeche             |
+------------------------------+

// in C#:
int laenge = int.Parse(Console.ReadLine());
int breite = int.Parse(Console.ReadLine());
int flaeche = laenge * breite;
Console.WriteLine(flaeche);

+--------------------------------+
|\         punkte >= 50 ?       /|
|  \ ja                  nein /  |
+---------------+----------------+
| Ausgabe:      | Ausgabe:       |
| "bestanden"   | "nicht         |
|               |  bestanden"    |
+---------------+----------------+

// in C#:
if (punkte >= 50)
{
    Console.WriteLine("bestanden");
}
else
{
    Console.WriteLine("nicht bestanden");
}

// Verschachtelt: Verzweigung in Schleife
// durch 3 teilbar → *, sonst die Zahl
+------------------------------+
| für i von 1 bis 6            |
|   +--------------------------+
|   |\     i MOD 3 = 0 ?     / |
|   |  \ ja           nein /   |
|   +------------+-------------+
|   | Ausgabe: * | Ausgabe: i  |
+---+------------+-------------+

// in C#:
for (int i = 1; i <= 6; i++)
{
    if (i % 3 == 0)
    {
        Console.Write("* ");
    }
    else
    {
        Console.Write(i + " ");
    }
}
// Ausgabe: 1 2 * 4 5 *
